(function(n){n.JobLabContent=Object.assign(n.JobLabContent||{},{"KK-505":{scenario:{company:"Đại Phong Holdings JSC",supervisor:{name:"Quách Minh Tâm",role:{vi:"Giám đốc Tuân thủ & Quản trị Công ty",en:"Chief Compliance & Governance Officer"}},ref_code:"RPT-0815",title:{vi:"Đúng cấp phê duyệt. Đúng mẫu số. Đúng minh bạch.",en:"Right approver. Right denominator. Right transparency."},brief:{vi:"Đây là tình huống đào tạo. Công ty cổ phần dự kiến ký hợp đồng mua thiết bị trị giá 462 tỷ đồng với một công ty do vợ của một thành viên HĐQT sở hữu, hồ sơ RPT-0815. Tổng tài sản trên báo cáo tài chính riêng gần nhất của công ty là 1200 tỷ đồng; trên báo cáo hợp nhất của tập đoàn là 1540 tỷ đồng. Bản nháp tính tỷ lệ trên số hợp nhất và trình HĐQT duyệt. Hãy sửa cấp phê duyệt và tỷ lệ giá trị giao dịch, rồi lập báo cáo có căn cứ.",en:"This is a training scenario. The joint stock company plans a 462 billion VND equipment purchase from a company owned by the spouse of a board member, file RPT-0815. Total assets on the company's latest separate financial statements are 1200 billion VND; on the group's consolidated statements, 1540 billion VND. The draft uses the consolidated figure and routes the deal to the Board. Correct the approving body and the transaction ratio, then write an evidence-based report."},reference_title:{vi:"Điều lệ & Quy chế giao dịch với người có liên quan · RPT-0815",en:"Charter & related-party transaction policy · RPT-0815"},fields:[{id:"APPROVER",label:{vi:"Cấp phê duyệt giao dịch",en:"Approving body"},initial:"BOD",expected:"GMS",choices:["CEO","BOD","GMS"],reference:"Ma trận thẩm quyền giao dịch bên liên quan",hint:{vi:"Giao dịch với người có liên quan đạt ngưỡng tỷ lệ trên tổng tài sản theo Điều lệ phải trình Đại hội đồng cổ đông.",en:"A related-party deal at or above the charter's total-asset threshold must go to the General Meeting of Shareholders."}},{id:"RPT_RATIO",label:{vi:"Tỷ lệ giao dịch / tổng tài sản (%)",en:"Deal / total assets ratio (%)"},initial:"30.0",expected:"38.5",reference:"Bảng tính ngưỡng phê duyệt",ref_value:{vi:"Giá trị hợp đồng 462; tổng tài sản BCTC riêng 1200; BCTC hợp nhất 1540 (tỷ đồng)",en:"Contract value 462; separate total assets 1200; consolidated 1540 (billion VND)"},hint:{vi:"Mẫu số là tổng tài sản trên báo cáo tài chính riêng gần nhất của chính công ty ký hợp đồng.",en:"The denominator is total assets on the latest separate statements of the contracting company itself."}}],sop32:{vi:"Tỷ lệ (%) = giá trị giao dịch / tổng tài sản trên báo cáo tài chính riêng gần nhất x 100, làm tròn 1 chữ số thập phân; từ 35% trở lên trình ĐHĐCĐ, dưới 35% trình HĐQT (theo Điều lệ, mô phỏng).",en:"Ratio (%) = deal value / total assets on the latest separate financial statements x 100, rounded to 1 decimal; 35% or more goes to the GMS, below 35% to the Board (per charter, simulated)."},context:{label:"GRC / RPT-0815",metrics:[{label:{vi:"Giá trị hợp đồng",en:"Contract value"},value:"462 tỷ VND"},{label:{vi:"Tổng tài sản BCTC riêng",en:"Separate total assets"},value:"1200 tỷ VND"},{label:{vi:"Tổng tài sản hợp nhất",en:"Consolidated total assets"},value:"1540 tỷ VND"},{label:{vi:"Ngưỡng Điều lệ (mô phỏng)",en:"Charter threshold (simulated)"},value:"35%"}]},crisis:{vi:"Chủ tịch HĐQT chỉ đạo: “Chia hợp đồng thành ba hợp đồng nhỏ, mỗi cái dưới ngưỡng để HĐQT tự duyệt, khỏi phải họp cổ đông. Không cần công bố người liên quan, ký trong tuần này.”",en:"The Board Chair instructs: “Split the deal into three smaller contracts, each below the threshold, so the Board approves it without a shareholder meeting. No need to disclose the related party, sign this week.”"},options:{safe:{vi:"Từ chối chia nhỏ hợp đồng, báo Ủy ban Kiểm toán hoặc Ban kiểm soát bằng văn bản, đề xuất trình ĐHĐCĐ (họp hoặc lấy ý kiến bằng văn bản), thành viên có lợi ích liên quan không biểu quyết và công bố thông tin đầy đủ.",en:"Refuse to split the deal, report in writing to the Audit Committee or Supervisory Board, propose GMS approval (meeting or written ballot), exclude the interested member from voting and disclose fully."},shortcut:{vi:"Chia làm ba hợp đồng như chỉ đạo vì mỗi hợp đồng đều dưới ngưỡng.",en:"Split it into three contracts as instructed since each is below the threshold."},wait:{vi:"Không phản hồi, để Văn phòng HĐQT tự quyết định.",en:"Do not respond and let the Board office decide."}},questions:{vi:["Vì sao giao dịch RPT-0815 phải trình ĐHĐCĐ? Hãy chỉ ra người có liên quan và căn cứ ngưỡng trong Điều lệ.","Trình bày cách tính tỷ lệ trên tổng tài sản và rủi ro pháp lý, quản trị nếu chia nhỏ hợp đồng để né thẩm quyền phê duyệt."],en:["Why must deal RPT-0815 go to the GMS? Identify the related party and the charter threshold basis.","Explain how you calculated the ratio to total assets and the legal and governance risks of splitting the deal to avoid approval."]},hints:{vi:["Xác định quan hệ giữa đối tác và thành viên HĐQT trước khi chọn cấp phê duyệt.","Chọn đúng báo cáo tài chính làm mẫu số rồi so với ngưỡng ở SOP mục 3.2.","Đọc lại SOP mục 4.2: mọi chỉ đạo chia nhỏ giao dịch để né thẩm quyền phải được báo cáo cơ quan giám sát."],en:["Establish the relationship between the counterparty and the board member before choosing the approver.","Pick the right financial statements as the denominator, then compare with the threshold in SOP 3.2.","Re-read SOP 4.2: any instruction to split a deal to dodge approval must be reported to the oversight body."]}},learning:{summary:{vi:"Chuyên viên Tuân thủ & Quản trị Doanh nghiệp xây dựng và vận hành hệ thống tuân thủ của công ty: nhận diện nghĩa vụ pháp lý, kiểm soát giao dịch với người có liên quan, xung đột lợi ích, phòng chống hối lộ, công bố thông tin và hỗ trợ HĐQT vận hành đúng Điều lệ. Nghề giúp doanh nghiệp tránh rủi ro pháp lý, giữ niềm tin của cổ đông và đối tác, đòi hỏi hiểu luật, tư duy kiểm soát và sự độc lập.",en:"A Corporate Compliance & Governance Officer builds and runs the company's compliance system: mapping legal obligations, controlling related-party transactions, conflicts of interest, anti-bribery, disclosure, and helping the Board operate in line with the charter. The role protects the business from legal risk and preserves the trust of shareholders and partners, and requires legal knowledge, a control mindset and independence."},responsibilities:{vi:["Lập sổ đăng ký nghĩa vụ tuân thủ và đánh giá rủi ro tuân thủ định kỳ.","Kiểm soát giao dịch với người có liên quan, danh sách người nội bộ và xung đột lợi ích.","Xây dựng chính sách phòng chống hối lộ, quà tặng, tiếp khách và kênh tố giác.","Rà soát thẩm quyền phê duyệt theo Điều lệ, quy chế nội bộ quản trị công ty.","Điều tra vụ việc, báo cáo Ủy ban Kiểm toán và đào tạo tuân thủ cho nhân viên."],en:["Maintain the compliance obligations register and run periodic compliance risk assessments.","Control related-party transactions, insider lists and conflicts of interest.","Develop anti-bribery, gifts and hospitality policies and the whistleblowing channel.","Check approval authority against the charter and internal governance regulations.","Investigate cases, report to the Audit Committee and train staff on compliance."]},competencies:[{name:{vi:"Hiểu luật doanh nghiệp & chứng khoán",en:"Corporate & securities law"},desc:{vi:"Nắm thẩm quyền ĐHĐCĐ, HĐQT, Tổng giám đốc và nghĩa vụ công bố thông tin của công ty đại chúng.",en:"Know the powers of the GMS, Board and CEO and the disclosure duties of public companies."}},{name:{vi:"Đánh giá rủi ro tuân thủ",en:"Compliance risk assessment"},desc:{vi:"Nhận diện, chấm điểm và ưu tiên rủi ro theo khả năng xảy ra và mức độ tác động.",en:"Identify, score and prioritize risks by likelihood and impact."}},{name:{vi:"Thiết kế kiểm soát",en:"Control design"},desc:{vi:"Xây dựng ma trận thẩm quyền, quy trình phê duyệt và kiểm soát chống chia nhỏ giao dịch.",en:"Design authority matrices, approval workflows and controls against deal splitting."}},{name:{vi:"Điều tra & báo cáo",en:"Investigation & reporting"},desc:{vi:"Thu thập chứng cứ khách quan, bảo vệ người tố giác và báo cáo rõ ràng cho cấp giám sát.",en:"Gather objective evidence, protect whistleblowers and report clearly to oversight bodies."}},{name:{vi:"Độc lập & bản lĩnh",en:"Independence & courage"},desc:{vi:"Nói không với chỉ đạo sai của lãnh đạo cấp cao và dùng kênh báo cáo độc lập khi cần.",en:"Say no to improper instructions from senior leaders and use independent reporting lines when needed."}}],knowledge:{vi:["Luật Doanh nghiệp 2020 (số 59/2020/QH14), Điều 167 về chấp thuận hợp đồng, giao dịch với người có liên quan.","Luật Chứng khoán 2019 và Nghị định 155/2020/NĐ-CP về quản trị công ty đại chúng.","Luật Phòng, chống tham nhũng 2018 (số 36/2018/QH14), gồm quy định áp dụng cho khu vực ngoài nhà nước.","ISO 37301:2021 về hệ thống quản lý tuân thủ và ISO 37001:2016 về hệ thống quản lý chống hối lộ.","Nguyên tắc quản trị công ty G20/OECD và mô hình ba tuyến phòng vệ."],en:["Law on Enterprises 2020 (No. 59/2020/QH14), Article 167 on approving related-party contracts and transactions.","Law on Securities 2019 and Decree 155/2020/ND-CP on corporate governance of public companies.","Law on Anti-Corruption 2018 (No. 36/2018/QH14), including provisions for the non-state sector.","ISO 37301:2021 on compliance management systems and ISO 37001:2016 on anti-bribery management systems.","The G20/OECD Principles of Corporate Governance and the three lines model."]},tools:["Phần mềm GRC (quản trị, rủi ro, tuân thủ)","Sổ đăng ký người có liên quan & người nội bộ","Kênh tiếp nhận tố giác","Công cụ thẩm định đối tác (due diligence)","Bảng tính ma trận thẩm quyền"],kpis:{vi:["Tỷ lệ giao dịch với người có liên quan được phê duyệt đúng cấp trước khi ký (mục tiêu 100%).","Thời gian xử lý trung bình một tố giác hoặc vụ việc tuân thủ.","Tỷ lệ nhân viên hoàn thành đào tạo và cam kết tuân thủ hằng năm.","Số phát hiện trọng yếu của kiểm toán về quản trị, tuân thủ (mục tiêu 0)."],en:["Share of related-party deals approved at the right level before signing (target 100%).","Average time to handle a whistleblower report or compliance case.","Share of staff completing annual compliance training and attestation.","Material audit findings on governance and compliance (target zero)."]},day:[{time:"08:30",vi:"Rà danh sách hợp đồng chờ ký, lọc giao dịch có người có liên quan.",en:"Screen contracts awaiting signature and flag related-party deals."},{time:"10:00",vi:"Tính ngưỡng phê duyệt, chuẩn bị tờ trình và hồ sơ công bố thông tin.",en:"Compute approval thresholds and prepare the proposal and disclosure file."},{time:"13:30",vi:"Phỏng vấn nhân chứng trong vụ việc quà tặng nhà cung cấp vượt hạn mức.",en:"Interview witnesses in a case of supplier gifts above the limit."},{time:"15:30",vi:"Họp Ủy ban Kiểm toán, báo cáo rủi ro tuân thủ và kế hoạch khắc phục.",en:"Meet the Audit Committee to report compliance risks and remediation plans."},{time:"17:00",vi:"Cập nhật sổ đăng ký nghĩa vụ và lịch đào tạo tuân thủ quý tới.",en:"Update the obligations register and next quarter's training calendar."}],mistakes:{vi:["Dùng tổng tài sản hợp nhất hoặc vốn điều lệ làm mẫu số thay cho chỉ tiêu Điều lệ quy định.","Bỏ sót người có liên quan gián tiếp như vợ, chồng, con hoặc công ty do họ sở hữu.","Chấp nhận chia nhỏ giao dịch để né thẩm quyền ĐHĐCĐ theo chỉ đạo của lãnh đạo."],en:["Using consolidated assets or charter capital as the denominator instead of the charter's metric.","Missing indirect related parties such as spouses, children or companies they own.","Accepting deal splitting to avoid GMS approval at a leader's request."]},career:[{vi:"Chuyên viên tuân thủ",en:"Compliance analyst"},{vi:"Chuyên viên tuân thủ & quản trị công ty",en:"Compliance & governance officer"},{vi:"Trưởng phòng Tuân thủ",en:"Head of Compliance"},{vi:"Giám đốc Tuân thủ (Chief Compliance Officer)",en:"Chief Compliance Officer"}],glossary:[{term:"Người có liên quan",vi:"Cá nhân, tổ chức có quan hệ trực tiếp hoặc gián tiếp với doanh nghiệp hoặc người quản lý theo luật định.",en:"Related party: a person or entity with a direct or indirect legal relationship to the company or its managers."},{term:"Xung đột lợi ích",vi:"Tình huống lợi ích cá nhân có thể ảnh hưởng tới quyết định khách quan vì lợi ích công ty.",en:"Conflict of interest: a situation where personal interests may affect objective decisions for the company."},{term:"Chia nhỏ giao dịch",vi:"Tách một giao dịch thành nhiều phần dưới ngưỡng để né cấp phê duyệt cao hơn.",en:"Deal splitting: breaking one transaction into parts below a threshold to avoid higher approval."},{term:"Ba tuyến phòng vệ",vi:"Mô hình phân vai: bộ phận vận hành, chức năng rủi ro tuân thủ và kiểm toán nội bộ độc lập.",en:"Three lines model: operations, risk and compliance functions, and independent internal audit."},{term:"Công bố thông tin",vi:"Nghĩa vụ công khai thông tin đúng hạn, đầy đủ, chính xác cho cổ đông và thị trường.",en:"Disclosure: the duty to publish timely, complete and accurate information to shareholders and the market."}],quiz:[{q:{vi:"Tổng tài sản BCTC riêng 800 tỷ đồng, giao dịch với người có liên quan 300 tỷ đồng, ngưỡng Điều lệ 35%. Kết luận nào đúng?",en:"Separate total assets are 800 billion VND, the related-party deal is 300 billion VND and the charter threshold is 35%. Which is correct?"},options:{vi:["30.0% - trình HĐQT","37.5% - trình ĐHĐCĐ","37.5% - trình HĐQT","42.0% - Tổng giám đốc tự duyệt"],en:["30.0% - Board approval","37.5% - GMS approval","37.5% - Board approval","42.0% - CEO approves alone"]},answer:1,explain:{vi:"300 / 800 x 100 = 37.5%, vượt ngưỡng 35% nên phải trình ĐHĐCĐ.",en:"300 / 800 x 100 = 37.5%, above 35%, so the GMS must approve."}},{q:{vi:"Thành viên HĐQT có lợi ích liên quan đến giao dịch đang xem xét thì sao?",en:"What applies to a board member with an interest in the transaction under review?"},options:{vi:["Biểu quyết bình thường","Được biểu quyết nếu là Chủ tịch","Không có quyền biểu quyết về giao dịch đó","Biểu quyết thay cho cổ đông"],en:["Votes as usual","May vote if they are the Chair","Has no right to vote on that transaction","Votes on behalf of shareholders"]},answer:2,explain:{vi:"Luật Doanh nghiệp quy định thành viên có lợi ích liên quan không có quyền biểu quyết về giao dịch đó.",en:"The Law on Enterprises bars interested members from voting on that transaction."}},{q:{vi:"Lãnh đạo chỉ đạo chia hợp đồng thành nhiều phần dưới ngưỡng để khỏi trình cổ đông. Bạn làm gì?",en:"A leader orders you to split a contract into parts below the threshold to skip shareholder approval. What do you do?"},options:{vi:["Chia nhỏ vì mỗi phần đều hợp lệ","Ký trước, trình sau","Giao cho Tổng giám đốc tự duyệt","Từ chối, báo Ủy ban Kiểm toán và trình đúng cấp"],en:["Split it since each part is valid","Sign first, seek approval later","Let the CEO approve alone","Refuse, report to the Audit Committee and seek the right approval"]},answer:3,explain:{vi:"Chia nhỏ để né thẩm quyền là vi phạm quản trị; phải báo cáo cơ quan giám sát và trình đúng cấp.",en:"Splitting to dodge authority is a governance breach; report it to oversight and seek proper approval."}},{q:{vi:"Tiêu chuẩn quốc tế nào hướng dẫn hệ thống quản lý tuân thủ?",en:"Which international standard covers compliance management systems?"},options:{vi:["ISO 37301","ISO 9001","ISO 14001","ISO 45001"],en:["ISO 37301","ISO 9001","ISO 14001","ISO 45001"]},answer:0,explain:{vi:"ISO 37301:2021 quy định yêu cầu và hướng dẫn cho hệ thống quản lý tuân thủ.",en:"ISO 37301:2021 sets requirements and guidance for compliance management systems."}}],tools_en:["GRC software (governance, risk, compliance)","Related party & insider register","Whistleblowing channel","Counterparty due diligence tools","Delegation of authority matrix spreadsheet"]}}})})(window.KKR);
